import React from "react";
import {
  FaBolt,
  FaUserGraduate,
  FaLeaf,
  FaBrain,
  FaTrophy,
  FaProjectDiagram,
  FaCalendarAlt,
  FaPalette
} from "react-icons/fa";

const Projects = () => {
  return (
    <section className="projects-page">

      {/* HEADER */}
      <div className="header">
        <h1>
          My Work <span>System</span>
        </h1>
        <p>Structured like a flow diagram of ideas → execution → impact</p>
      </div>

      {/* FLOW DIAGRAM */}
      <div className="flow">

        <div className="line"></div>

        {/* ENERGY PULSE */}
        <div className="node left">
          <div className="dot"><FaBolt /></div>
          <div className="card">
            <h3>EnergyPulse</h3>
            <p>AI-based smart home dashboard for real-time energy & biometric monitoring.</p>
            <span>React.js</span>
          </div>
        </div>

        {/* STUDENT PORTAL */}
        <div className="node right">
          <div className="dot"><FaUserGraduate /></div>
          <div className="card">
            <h3>Student Portal</h3>
            <p>Full-stack system for managing student records and academic data efficiently.</p>
            <span>Spring Boot • MySQL • JS</span>
          </div>
        </div>

        {/* COGNI FLOW */}
        <div className="node left">
          <div className="dot"><FaBrain /></div>
          <div className="card highlight">
            <h3>Cogni Flow</h3>
            <p>
              Interactive cognitive learning interface focused on structured thinking,
              problem solving flow visualization and UI-based reasoning systems.
            </p>
            <span>HTML • CSS • JavaScript</span>
          </div>
        </div>

        {/* FARM2FORK */}
        <div className="node right">
          <div className="dot"><FaLeaf /></div>
          <div className="card">
            <h3>Farm2Fork</h3>
            <p>Frontend platform connecting farmers and consumers through seamless UI flow.</p>
            <span>HTML • CSS • JS</span>
          </div>
        </div>

      </div>

      {/* ACHIEVEMENTS */}
      <div className="ach">

        <h2>Achievements</h2>

        <div className="ach-grid">

          <div className="ach-card">
            <FaTrophy />
            <h3>Hackathons</h3>
            <p>SIH 2025 Semi-Finalist with problem-solving innovation.</p>
          </div>

          <div className="ach-card">
            <FaProjectDiagram />
            <h3>Best Project</h3>
            <p>Won award for Li-Fi based innovation at conference.</p>
          </div>

          <div className="ach-card">
            <FaCalendarAlt />
            <h3>Events</h3>
            <p>Organized Code Crunch DSA challenge event.</p>
          </div>

          <div className="ach-card">
            <FaPalette />
            <h3>Coordination</h3>
            <p>Managed technical and non-technical college events.</p>
          </div>

        </div>
      </div>

      {/* STYLE */}
      <style>{`

        .projects-page {
          min-height: 100vh;
          padding: 60px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 60px;
        }

        .header h1 {
          font-size: 42px;
        }

        .header span {
          color: #38BDF8;
        }

        .header p {
          color: #94a3b8;
          margin-top: 8px;
        }

        /* FLOW */
        .flow {
          position: relative;
          max-width: 900px;
          margin: auto;
        }

        .line {
          position: absolute;
          width: 2px;
          height: 100%;
          background: rgba(56,189,248,0.3);
          left: 50%;
          transform: translateX(-50%);
        }

        /* NODE */
        .node {
          display: flex;
          align-items: center;
          margin: 50px 0;
          position: relative;
        }

        .node.left {
          justify-content: flex-start;
        }

        .node.right {
          justify-content: flex-end;
        }

        /* DOT */
        .dot {
          width: 45px;
          height: 45px;
          border-radius: 50%;
          background: rgba(56,189,248,0.15);
          border: 1px solid #38BDF8;
          display: flex;
          align-items: center;
          justify-content: center;
          color: #38BDF8;
          box-shadow: 0 0 15px rgba(56,189,248,0.4);
          z-index: 2;
        }

        /* CARD */
        .card {
          width: 300px;
          padding: 16px;
          margin: 0 20px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          border-radius: 14px;
          transition: 0.3s;
        }

        .card:hover {
          transform: scale(1.03);
          box-shadow: 0 0 20px rgba(56,189,248,0.3);
        }

        .highlight {
          border: 1px solid #38BDF8;
          box-shadow: 0 0 25px rgba(56,189,248,0.2);
        }

        .card h3 {
          color: #38BDF8;
          margin-bottom: 6px;
        }

        .card p {
          font-size: 14px;
          color: #cbd5e1;
        }

        .card span {
          display: inline-block;
          margin-top: 10px;
          font-size: 12px;
          color: #94a3b8;
        }

        /* ACHIEVEMENTS */
        .ach {
          margin-top: 80px;
        }

        .ach h2 {
          text-align: center;
          color: #38BDF8;
          margin-bottom: 30px;
        }

        .ach-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 20px;
        }

        .ach-card {
          padding: 18px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          border-radius: 14px;
          text-align: center;
          transition: 0.3s;
        }

        .ach-card:hover {
          transform: translateY(-5px);
          box-shadow: 0 0 20px rgba(56,189,248,0.25);
        }

        .ach-card svg {
          color: #38BDF8;
          font-size: 22px;
          margin-bottom: 8px;
        }

        .ach-card h3 {
          color: #38BDF8;
        }

        .ach-card p {
          color: #cbd5e1;
          font-size: 13px;
        }

        @media (max-width: 900px) {
          .line {
            left: 20px;
          }

          .node {
            justify-content: flex-start !important;
          }

          .card {
            width: 100%;
          }

          .ach-grid {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
